export function verse(n: number): string {
  if (n < 1 || n > 8 || !Number.isInteger(n)) {
    throw new Error("Invalid verse number");
  }

  const animals = [
    "fly",
    "spider",
    "bird",
    "cat",
    "dog",
    "goat",
    "cow",
    "horse",
  ];

  const reactions = [
    "",
    "It wriggled and jiggled and tickled inside her.",
    "How absurd to swallow a bird!",
    "Imagine that, to swallow a cat!",
    "What a hog, to swallow a dog!",
    "Just opened her throat and swallowed a goat!",
    "I don't know how she swallowed a cow!",
    "She's dead, of course!",
  ];

  let lines: string[] = [];

  // First line
  lines.push(`I know an old lady who swallowed a ${animals[n - 1]}.`);

  // Special case for horse (last verse)
  if (n === 8) {
    lines.push(reactions[n - 1]);
    return lines.join("\n") + "\n";
  }

  // Reaction line (if any)
  if (reactions[n - 1]) {
    lines.push(reactions[n - 1]);
  }

  // Cumulative "She swallowed..." lines
  for (let i = n; i > 1; i--) {
    const currentAnimal = animals[i - 1];
    const previousAnimal = animals[i - 2];
    let line = `She swallowed the ${currentAnimal} to catch the ${previousAnimal}.`;

    // Special case for spider description: append to the previous animal's name
    if (previousAnimal === "spider") {
      line += " that wriggled and jiggled and tickled inside her.";
    }

    lines.push(line);
  }

  // Final line for all verses except the last one
  if (n !== 8) {
    lines.push("I don't know why she swallowed the fly. Perhaps she'll die.");
  }

  return lines.join("\n") + "\n";
}

export function verses(start: number, end: number): string {
  if (start < 1 || end > 8 || start > end || !Number.isInteger(start) || !Number.isInteger(end)) {
    throw new Error("Invalid verse range");
  }

  const result: string[] = [];
  for (let i = start; i <= end; i++) {
    result.push(verse(i));
  }

  return result.join("\n");
}

import * as arc from "open-arc";

export type IsPairedFn = (input: string) => boolean;

export const isPairedSpec = arc.defineRegion<IsPairedFn>({
  "id": "matchingBrackets.isPaired",
  "intent": "Exercise \"matching-brackets\": implement `isPaired`.\n\nGiven a string containing brackets `[]`, braces `{}`, parentheses `()`, or any combination thereof, verify that any and all pairs are matched and nested correctly.\nAny other characters should be ignored.\nFor example, `\"{what is (42)}?\"` is balanced and `\"[text}\"` is not.",
  "examples": [
    {
      "name": "Matching Brackets > paired square brackets",
      "args": [
        "[]"
      ],
      "expected": true
    },
    {
      "name": "Matching Brackets > empty string",
      "args": [
        ""
      ],
      "expected": true
    },
    {
      "name": "Matching Brackets > unpaired brackets",
      "args": [
        "[["
      ],
      "expected": false
    }
  ]
});

// @openarc:begin matchingBrackets.isPaired
export const isPaired: IsPairedFn = (input) => {
  const stack: string[] = [];
  const pairs: Record<string, string> = { "]": "[", "}": "{", ")": "(" };
  for (const char of input) {
    if ("[({".includes(char)) {
      stack.push(char);
    } else if ("]})".includes(char)) {
      if (stack.length === 0 || stack.pop() !== pairs[char]) {
        return false;
      }
    }
  }
  return stack.length === 0;
};
// @openarc:end matchingBrackets.isPaired

export function isPaired(input: string): boolean {
  const stack: string[] = [];
  const pairs: Record<string, string> = {
    ']': '[',
    '}': '{',
    ')': '(',
  };

  for (const char of input) {
    if (char === '[' || char === '{' || char === '(') {
      stack.push(char);
    } else if (char === ']' || char === '}' || char === ')') {
      if (stack.length === 0 || stack[stack.length - 1] !== pairs[char]) {
        return false;
      }
      stack.pop();
    }
    // Ignore any other characters
  }

  return stack.length === 0;
}

import * as arc from "open-arc";

export type AnnotateFn = (field: string[]) => string[];

export const annotateSpec = arc.defineRegion<AnnotateFn>({
  "id": "minesweeper.annotate",
  "intent": "Exercise \"minesweeper\": implement `annotate`.\n\nYour task is to add the mine counts to empty squares in a completed Minesweeper board.\nThe board itself is a rectangle composed of squares that are either empty (`' '`) or a mine (`'*'`).\n\nFor each empty square, count the number of mines adjacent to it (horizontally, vertically, diagonally).\nIf the empty square has no adjacent mines, leave it empty.\nOtherwise replace it with the adjacent mines count.\n\nFor example, you may receive a 5 x 4 board like this (empty spaces are represented here with the '·' character for display on screen):\n\n```text\n·*·*·\n··*··\n··*··\n·····\n```\n\nWhich your code should transform into this:\n\n```text\n1*3*1\n13*31\n·2*2·\n·111·\n```",
  "examples": [
    {
      "name": "Minesweeper annotate > handles no rows",
      "args": [
        []
      ],
      "expected": []
    },
    {
      "name": "Minesweeper annotate > handles no columns",
      "args": [
        [
          ""
        ]
      ],
      "expected": [
        ""
      ]
    },
    {
      "name": "Minesweeper annotate > handles no mines",
      "args": [
        [
          "   ",
          "   ",
          "   "
        ]
      ],
      "expected": [
        "   ",
        "   ",
        "   "
      ]
    }
  ]
});

// @openarc:begin minesweeper.annotate
export const annotate: AnnotateFn = (field) => {
  const rows = field.length;
  if (rows === 0) return [];
  const cols = field[0].length;
  if (cols === 0) return field;
  const result = [];
  for (let r = 0; r < rows; r++) {
    const newRow = [];
    for (let c = 0; c < cols; c++) {
      if (field[r][c] === '*') {
        newRow.push('*');
      } else {
        let count = 0;
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            if (dr === 0 && dc === 0) continue;
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && field[nr][nc] === '*') {
              count++;
            }
          }
        }
        newRow.push(count > 0 ? count.toString() : ' ');
      }
    }
    result.push(newRow.join(''));
  }
  return result;
};
// @openarc:end minesweeper.annotate

export function annotate(field: string[]): string[] {
  if (field.length === 0) {
    return [];
  }

  const rows = field.length;
  const cols = field[0].length;

  // Handle cases where rows might be empty strings or inconsistent lengths
  // though the problem implies a valid rectangle. We'll assume valid input based on examples.
  // If a row is shorter than cols, we treat it as having spaces up to cols? 
  // The examples suggest consistent rectangles. Let's stick to the grid dimensions defined by the first row.

  // Create a 2D array to store the mine counts for empty cells
  // We will modify the input array in place or create a new one. 
  // Since we need to return a new array of strings, let's build the result.

  const result: string[] = [];

  for (let r = 0; r < rows; r++) {
    const rowStr = field[r];
    const rowLen = rowStr.length;

    // If the row is empty string, push empty string and continue
    if (rowLen === 0) {
      result.push("");
      continue;
    }

    const newRowChars: string[] = [];

    for (let c = 0; c < rowLen; c++) {
      const cell = rowStr[c];

      if (cell === '*') {
        newRowChars.push('*');
      } else {
        // It's an empty square (' ')
        let mineCount = 0;

        // Check all 8 neighbors
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            // Skip the cell itself
            if (dr === 0 && dc === 0) continue;

            const nr = r + dr;
            const nc = c + dc;

            // Check bounds
            if (nr >= 0 && nr < rows && nc >= 0 && nc < rowLen) {
              if (field[nr][nc] === '*') {
                mineCount++;
              }
            }
          }
        }

        if (mineCount > 0) {
          newRowChars.push(mineCount.toString());
        } else {
          newRowChars.push(' ');
        }
      }
    }

    result.push(newRowChars.join(''));
  }

  return result;
}

import * as arc from "open-arc";

export type CleanFn = (input: string) => string;

export const cleanSpec = arc.defineRegion<CleanFn>({
  "id": "phoneNumber.clean",
  "intent": "Exercise "phone-number": implement `clean`.

Clean up phone numbers so that they can be sent SMS messages.

The **North American Numbering Plan (NANP)** is a telephone numbering system used by many countries in North America like the United States, Canada or Bermuda.
All NANP-countries share the same international country code: `1`.

NANP numbers are ten-digit numbers consisting of a three-digit Numbering Plan Area code, commonly known as _area code_, followed by a seven-digit local number.
The first three digits of the local number represent the _exchange code_, followed by the unique four-digit number which is the _subscriber number_.

The format is usually represented as

```text
NXX NXX-XXXX
```

where `N` is any digit from 2 through 9 and `X` is any digit from 0 through 9.

Sometimes they also have the country code (represented as `1` or `+1`) prefixed.

Your task is to clean up differently formatted telephone numbers by removing punctuation and the country code if present.

For example, the inputs

- `+1 (613)-995-0253`
- `613-995-0253`
- `1 613 995 0253`
- `613.995.0253`

should all produce the output

`6139950253`

**Note:** As this exercise only deals with telephone numbers used in NANP-countries, only 1 is considered a valid country code.",
