// @openarc:begin pigLatin.translate
export const translate: TranslateFn = (phrase) => {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  const translateWord = (word: string): string => {
    if (vowels.has(word[0]) || word.startsWith('xr') || word.startsWith('yt')) {
      return word + 'ay';
    }
    let i = 0;
    while (i < word.length) {
      const char = word[i];
      if (char === 'y' && i > 0) {
        break;
      }
      if (vowels.has(char) && char !== 'u') {
        if (word[i + 1] === 'u') {
          i++;
        }
        break;
      }
      i++;
    }
    return word.slice(i) + word.slice(0, i) + 'ay';
  };
  return phrase.split(' ').map(translateWord).join(' ');
};
// @openarc:end pigLatin.translate

export function translate(phrase: string): string {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);

  const translateWord = (word: string): string => {
    const lowerWord = word.toLowerCase();

    // Rule 1: Starts with vowel, "xr", or "yt"
    if (
      vowels.has(lowerWord[0]) ||
      lowerWord.startsWith('xr') ||
      lowerWord.startsWith('yt')
    ) {
      return word + 'ay';
    }

    let i = 0;
    const len = lowerWord.length;

    // Check for "qu" at the start (Rule 3)
    if (lowerWord.startsWith('qu')) {
      return word.slice(2) + 'qu' + 'ay';
    }

    // Find the split point for consonants
    while (i < len) {
      const char = lowerWord[i];

      // Rule 4: 'y' acts as a vowel if preceded by consonants
      if (char === 'y' && i > 0) {
        break;
      }

      // If we hit a standard vowel, stop
      if (vowels.has(char)) {
        break;
      }

      // If we hit 'qu' (and it's not at index 0, handled above, but good for safety)
      if (char === 'q' && i + 1 < len && lowerWord[i + 1] === 'u') {
        i += 2;
        break;
      }

      i++;
    }

    // If we went through the whole word without finding a vowel split (e.g., "rhythm" -> 'y' handled, or all consonants)
    // Note: "rhythm" breaks at 'y' (i=2). "gym" breaks at 'y' (i=1).
    // If no vowel or special 'y' found, i will be len.
    // However, Rule 2 says move consonants to end. If the word is all consonants (unlikely in English but possible), we move all.
    // Actually, if 'y' is at the start (e.g., "yellow"), it acts as a vowel per Rule 1 logic? 
    // Rule 1 says "starts with vowel". 'y' is not in the vowel set. 
    // Rule 4 says "starts with one or more consonants followed by y". 
    // So "yellow": starts with 'y'. Is 'y' a consonant here? 
    // Rule 4 implies 'y' is the vowel trigger. If 'y' is at index 0, there are 0 consonants preceding it.
    // So "yellow" -> "ellowy" + "ay" -> "ellowyay".
    // Let's re-verify Rule 4: "starts with one or more consonants followed by y".
    // If 0 consonants, it falls through to Rule 1? No, 'y' is not in vowels.
    // So "yellow" would fall through the loop? 
    // Loop: i=0, char='y'. i>0 is false. vowels.has('y') is false. 
    // Loop continues? No, 'y' is not 'q'. i becomes 1.
    // Next iteration i=1, char='e'. vowels.has('e') is true. Break.
    // Split at 1. "ellow" + "y" + "ay" -> "ellowyay". Correct.

    // What if word is "my"? 
    // i=0, char='m'. Consonant. i=1.
    // i=1, char='y'. i>0 is true. Break.
    // Split at 1. "y" + "m" + "ay" -> "ymay". Correct.

    // What if word is "rhythm"?
    // i=0 'r', i=1 'h', i=2 'y'. Break.
    // Split at 2. "ythm" + "rh" + "ay" -> "ythmrhay". Correct.

    // What if word is "chair"?
    // i=0 'c', i=1 'h', i=2 'a'. Break.
    // Split at 2. "air" + "ch" + "ay" -> "airchay". Correct.

    // What if word is "quick"?
    // Starts with 'qu'. Handled by specific check at top. Returns "ickquay".

    // What if word is "square"?
    // i=0 's'. i=1 'q'. i=2 'u'. 
    // Check 'qu' at top? No, starts with 's'.
    // Loop:
    // i=0 's'. Consonant. i=1.
    // i=1 'q'. Not 'y'. Not vowel. 
    // Check 'q' and next is 'u'. Yes. i += 2 -> i=3. Break.
    // Split at 3. "are" + "squ" + "ay" -> "aresquay". Correct.

    const prefix = word.slice(0, i);
    const suffix = word.slice(i);
    return suffix + prefix + 'ay';
  };

  return phrase
    .split(' ')
    .map(translateWord)
    .join(' ');
}

