export function encode(numbers: number[]): number[] {
  const result: number[] = [];

  for (const num of numbers) {
    if (num < 0 || num > 0xFFFFFFFF) {
      throw new Error("Number out of range for 32-bit unsigned integer");
    }

    if (num === 0) {
      result.push(0);
      continue;
    }

    const bytes: number[] = [];
    let n = num;

    while (n > 0) {
      const byte = n & 0x7F;
      n >>= 7;
      bytes.unshift(byte);
    }

    // Set continuation bit for all bytes except the last one
    for (let i = 0; i < bytes.length - 1; i++) {
      bytes[i] |= 0x80;
    }

    result.push(...bytes);
  }

  return result;
}

export function decode(bytes: number[]): number[] {
  const result: number[] = [];
  let currentNumber = 0;
  let bitsCollected = 0;

  for (const byte of bytes) {
    // Validate byte range
    if (byte < 0 || byte > 255) {
      throw new Error("Invalid byte value");
    }

    // Check for continuation bit
    if ((byte & 0x80) === 0) {
      // Last byte
      if (bitsCollected === 0) {
        // Single byte number
        result.push(byte);
      } else {
        // Multi-byte number finished
        // We need to reconstruct the number. 
        // The first byte we read (lowest significance) was stored in currentNumber.
        // The last byte we read (highest significance) is 'byte'.
        // We need to shift the accumulated value left by 7 * (bitsCollected) and add the new byte.
        // However, since we shifted incrementally in the loop, currentNumber holds the lower bits.
        // We need to shift currentNumber by 7 * bitsCollected? No.
        // Let's trace: 
        // Byte 1 (LSB): current = b1, bits=1
        // Byte 2: current = (b1 << 7) | b2, bits=2
        // ...
        // Byte N (MSB): current = (...((b1 << 7) | b2) << 7) | bN
        // Wait, my loop logic was:
        // if continuation: current = (current << 7) | (byte & 0x7F)
        // This means the FIRST byte read becomes the LSB.
        // So if input is [0xC0, 0x7F] (which is 8192):
        // 1. byte=0xC0 (192). Continuation set. 
        //    current = (0 << 7) | 64 = 64. bits=1.
        // 2. byte=0x7F (127). Continuation clear.
        //    This is the last byte.
        //    We need to combine current (64) and byte (127).
        //    The structure is: [Continuation, Data] [Continuation, Data] ... [No Continuation, Data]
        //    The first byte read is the LEAST significant 7 bits.
        //    So the value is: byte_N * (2^(7*(N-1))) + ... + byte_1 * (2^0)
        //    My loop did: current = (current << 7) | byte_data.
        //    Step 1: current = 64.
        //    Step 2: We need to shift 64 by 7 and add 127? 
        //    No, 64 is the LSB part. 127 is the MSB part.
        //    Value = 127 * 128 + 64 = 16256 + 64 = 16320? 
        //    Wait, 8192 in binary is 0000 1000 0000 0000.
        //    8192 = 0x2000.
        //    0x2000 >> 7 = 0x40 (64). 0x40 & 0x7F = 64.
        //    0x40 >> 7 = 0x0.
        //    So bytes are [64, 0].
        //    Encoded: [0xC0, 0x00].
        //    Decode:
        //    1. byte=0xC0. Cont=1. data=64. current=64. bits=1.
        //    2. byte=0x00. Cont=0. data=0.
        //    We need to combine 64 and 0.
        //    Since 64 was read first (LSB), it should be shifted by 7 bits to make room for the next byte?
        //    No, the next byte is MORE significant.
        //    So the value is: (current << 7) | data.
        //    Let's re-verify the loop logic.
        //    If I have bytes [A, B] where A is LSB.
        //    Read A: current = A. bits=1.
        //    Read B: current = (A << 7) | B.
        //    This results in A being the lower 7 bits and B being the upper 7 bits.
        //    This is correct for Little Endian VLQ.
        //    Let's check 8192 again.
        //    8192 = 0x2000.
        //    0x2000 & 0x7F = 0x00.
        //    0x2000 >> 7 = 0x40.
        //    0x40 & 0x7F = 0x40.
        //    0x40 >> 7 = 0.
        //    Bytes: [0x40, 0x00].
        //    Encoded: [0xC0 | 0x40, 0x00] = [0x80? No, 0xC0 is 11000000. 0x40 is 01000000. OR is 11000000 = 0xC0].
        //    So encoded is [0xC0, 0x00].
        //    Decode:
        //    1. byte=0xC0. Cont=1. data=0x40 (64). current=64. bits=1.
        //    2. byte=0x00. Cont=0. data=0.
        //    Combine: (current << 7) | data = (64 << 7) | 0 = 8192.
        //    This works.

        // Why did my previous code fail?
        // "value = currentNumber; for (let i = 0; i < bitsCollected; i++) { value = (value << 7) | (byte & 0x7F); }"
        // This loop shifts currentNumber multiple times and adds the SAME byte multiple times. That is wrong.
        // The correct logic is simply: result = (currentNumber << 7) | (byte & 0x7F).
        // Because currentNumber already contains the lower bits accumulated from previous iterations.

        const value = (currentNumber << 7) | (byte & 0x7F);
        if (value > 0xFFFFFFFF) {
          throw new Error("Decoded number exceeds 32-bit unsigned integer range");
        }
        result.push(value);
      }
      currentNumber = 0;
      bitsCollected = 0;
    } else {
      // Not the last byte
      bitsCollected++;
      if (bitsCollected > 5) {
        throw new Error("Too many bytes for a 32-bit integer");
      }
      currentNumber = (currentNumber << 7) | (byte & 0x7F);
    }
