  // If we ended without finishing a number, it's an error
  if (bitsCollected !== 0) {
    throw new Error("Incomplete VLQ sequence");
  }

  return result;
}

export function answer(question: string): number {
  if (!question || typeof question !== "string") {
    throw new Error("Invalid question");
  }

  const trimmed = question.trim();
  if (!trimmed.startsWith("What is ")) {
    throw new Error("Unknown operation");
  }

  // Extract the expression part between "What is " and the final "?"
  const expression = trimmed.slice(8, -1).trim();
  if (!expression) {
    throw new Error("Syntax error");
  }

  // Tokenize the expression
  // We split by spaces, but we need to handle negative numbers correctly.
  // A simple regex split might break on negative numbers if they are at the start or after an operator.
  // Strategy: Match numbers (including negatives) and operators as tokens.

  const tokens: string[] = [];
  let i = 0;
  const len = expression.length;

  while (i < len) {
    const char = expression[i];

    // Check for operators
    if (["+", "-", "*", "/"].includes(char)) {
      tokens.push(char);
      i++;
      continue;
    }

    // Check for numbers (including negative numbers)
    // A number can start with a minus sign if it's the first token or follows an operator
    let numStr = "";
    if (char === "-" && (i === 0 || ["+", "-", "*", "/"].includes(expression[i - 1]))) {
      // Potential negative number
      let j = i + 1;
      while (j < len && (expression[j] >= "0" && expression[j] <= "9")) {
        numStr += expression[j];
        j++;
      }
      if (numStr === "") {
        // It was just a minus sign, which is invalid syntax in this context unless it's part of a number
        // But we handled the case where it starts a number. If no digits follow, it's an error.
        // However, we need to be careful: "5 minus -3" -> tokens: "5", "minus", "-3"
        // Our logic above handles the '-' as an operator if it follows an operator.
        // If it's at the start, it's a negative number.
        // If it follows a number (e.g. "5 -"), that's invalid syntax handled later.
        throw new Error("Syntax error");
      }
      tokens.push("-" + numStr);
      i = j;
      continue;
    }

    // Check for digits
    if (char >= "0" && char <= "9") {
      let j = i;
      while (j < len && expression[j] >= "0" && expression[j] <= "9") {
        numStr += expression[j];
        j++;
      }
      tokens.push(numStr);
      i = j;
      continue;
    }

    // If we encounter anything else, it's invalid syntax
    throw new Error("Syntax error");
  }

  // Validate tokens
  if (tokens.length === 0) {
    throw new Error("Syntax error");
  }

  // Parse numbers and operators
  const numbers: number[] = [];
  const operators: string[] = [];

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    if (i === 0) {
      // First token must be a number
      if (!/^-?\d+$/.test(token)) {
        throw new Error("Syntax error");
      }
      numbers.push(parseInt(token, 10));
    } else {
      // Check if it's an operator
      if (["+", "-", "*", "/"].includes(token)) {
        operators.push(token);
      } else {
        // Check if it's a number (e.g., after an operator)
        if (!/^-?\d+$/.test(token)) {
          throw new Error("Unknown operation");
        }
        numbers.push(parseInt(token, 10));
      }
    }
  }

  // Validate structure: must alternate Number, Operator, Number, ...
  // The last token must be a number.
  if (numbers.length === 0) {
    throw new Error("Syntax error");
  }

  // Check for consecutive operators or missing numbers
  // We already pushed numbers and operators into separate arrays based on position.
  // Let's reconstruct the logic to ensure strict alternation.

  // Re-verify the token stream logic against the arrays
  // Actually, the loop above pushes to numbers or operators.
  // We need to ensure that we don't have two operators in a row or two numbers in a row (except the start).

  // Let's rebuild the validation:
  // tokens[0] must be number
  // tokens[1] must be operator
  // tokens[2] must be number
  // tokens[3] must be operator
  // ...
  // tokens[last] must be number

  if (tokens.length === 0) throw new Error("Syntax error");

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (i % 2 === 0) {
      // Even index (0, 2, 4...) should be a number
      if (!/^-?\d+$/.test(token)) {
        throw new Error("Syntax error");
      }
    } else {
      // Odd index (1, 3, 5...) should be an operator
      if (!["+", "-", "*", "/"].includes(token)) {
        throw new Error("Unknown operation");
      }
    }
  }

  // Now we have valid tokens. Convert to numbers and operators arrays for calculation.
  // numbers array will contain all numbers in order.
  // operators array will contain all operators in order.

  const numTokens: number[] = [];
  const opTokens: string[] = [];

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (i % 2 === 0) {
      numTokens.push(parseInt(token, 10));
    } else {
      opTokens.push(token);
    }
  }

  // Evaluate left-to-right
  let result = numTokens[0];

  for (let i = 0; i < opTokens.length; i++) {
    const op = opTokens[i];
    const nextNum = numTokens[i + 1];

    switch (op) {
      case "+":
        result += nextNum;
        break;
      case "-":
        result -= nextNum;
        break;
      case "*":
        result *= nextNum;
        break;
      case "/":
        if (nextNum === 0) {
          throw new Error("Division by zero");
        }
        result = Math.trunc(result / nextNum);
        break;
      default:
        throw new Error("Unknown operation");
    }
  }

  return result;
}

