// @openarc:begin minesweeper.annotate
export const annotate: AnnotateFn = (field) => {
  const rows = field.length;
  if (rows === 0) return [];
  const cols = field[0].length;
  if (cols === 0) return field;
  const result = [];
  for (let r = 0; r < rows; r++) {
    const newRow = [];
    for (let c = 0; c < cols; c++) {
      if (field[r][c] === '*') {
        newRow.push('*');
      } else {
        let count = 0;
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            if (dr === 0 && dc === 0) continue;
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && field[nr][nc] === '*') {
              count++;
            }
          }
        }
        newRow.push(count > 0 ? count.toString() : ' ');
      }
    }
    result.push(newRow.join(''));
  }
  return result;
};
// @openarc:end minesweeper.annotate

export function annotate(field: string[]): string[] {
  if (field.length === 0) {
    return [];
  }

  const rows = field.length;
  const cols = field[0].length;

  // Handle cases where rows might be empty strings or inconsistent lengths
  // though the problem implies a valid rectangle. We'll assume valid input based on examples.
  // If a row is shorter than cols, we treat it as having spaces up to cols? 
  // The examples suggest consistent rectangles. Let's stick to the grid dimensions defined by the first row.

  // Create a 2D array to store the mine counts for empty cells
  // We will modify the input array in place or create a new one. 
  // Since we need to return a new array of strings, let's build the result.

  const result: string[] = [];

  for (let r = 0; r < rows; r++) {
    const rowStr = field[r];
    const rowLen = rowStr.length;

    // If the row is empty string, push empty string and continue
    if (rowLen === 0) {
      result.push("");
      continue;
    }

    const newRowChars: string[] = [];

    for (let c = 0; c < rowLen; c++) {
      const cell = rowStr[c];

      if (cell === '*') {
        newRowChars.push('*');
      } else {
        // It's an empty square (' ')
        let mineCount = 0;

        // Check all 8 neighbors
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            // Skip the cell itself
            if (dr === 0 && dc === 0) continue;

            const nr = r + dr;
            const nc = c + dc;

            // Check bounds
            if (nr >= 0 && nr < rows && nc >= 0 && nc < rowLen) {
              if (field[nr][nc] === '*') {
                mineCount++;
              }
            }
          }
        }

        if (mineCount > 0) {
          newRowChars.push(mineCount.toString());
        } else {
          newRowChars.push(' ');
        }
      }
    }

    result.push(newRowChars.join(''));
  }

  return result;
}

import * as arc from "open-arc";

export type CleanFn = (input: string) => string;

export const cleanSpec = arc.defineRegion<CleanFn>({
  "id": "phoneNumber.clean",
  "intent": "Exercise "phone-number": implement `clean`.

Clean up phone numbers so that they can be sent SMS messages.

The **North American Numbering Plan (NANP)** is a telephone numbering system used by many countries in North America like the United States, Canada or Bermuda.
All NANP-countries share the same international country code: `1`.

NANP numbers are ten-digit numbers consisting of a three-digit Numbering Plan Area code, commonly known as _area code_, followed by a seven-digit local number.
The first three digits of the local number represent the _exchange code_, followed by the unique four-digit number which is the _subscriber number_.

The format is usually represented as

```text
NXX NXX-XXXX
```

where `N` is any digit from 2 through 9 and `X` is any digit from 0 through 9.

Sometimes they also have the country code (represented as `1` or `+1`) prefixed.

Your task is to clean up differently formatted telephone numbers by removing punctuation and the country code if present.

For example, the inputs

- `+1 (613)-995-0253`
- `613-995-0253`
- `1 613 995 0253`
- `613.995.0253`

should all produce the output

`6139950253`

**Note:** As this exercise only deals with telephone numbers used in NANP-countries, only 1 is considered a valid country code.",
  "examples": [
    {
      "name": "Phone Number > Cleanup user-entered phone numbers > cleans the number",
      "args": [
        "(223) 456-7890"
      ],
      "expected": "2234567890"
    },
    {
      "name": "Phone Number > Cleanup user-entered phone numbers > cleans numbers with dots",
      "args": [
        "223.456.7890"
      ],
      "expected": "2234567890"
    }
  ]
});

// @openarc:begin phoneNumber.clean
export const clean: CleanFn = (input) => arc.todo("phoneNumber.clean");
// @openarc:end phoneNumber.clean

export function clean(input: string): string {
  // Remove all non-digit characters
  const digits = input.replace(/\D/g, "");

  // Handle country code
  if (digits.length === 11) {
    if (digits[0] !== "1") {
      throw new Error("11 digits must start with 1");
    }
    digits = digits.slice(1);
  }

  // Validate length after removing country code
  if (digits.length !== 10) {
    throw new Error("Incorrect phone number length");
  }

  // Validate area code (first digit must be 2-9)
  if (digits[0] < "2" || digits[0] > "9") {
    throw new Error("Area code cannot start with zero or one");
  }

  // Validate exchange code (fourth digit must be 2-9)
  if (digits[3] < "2" || digits[3] > "9") {
    throw new Error("Exchange code cannot start with zero or one");
  }

  return digits;
}

