// @openarc:begin diamond.makeDiamond
export const makeDiamond: MakeDiamondFn = (character) => {
  const n = character.charCodeAt(0) - 65;
  const lines = [];
  for (let i = 0; i <= n; i++) {
    const spaces = ' '.repeat(n - i);
    const chars = i === 0 ? 'A' : String.fromCharCode(65 + i) + ' '.repeat(2 * i - 1) + String.fromCharCode(65 + i);
    lines.push(spaces + chars + spaces);
  }
  for (let i = n - 1; i >= 0; i--) {
    lines.push(lines[i]);
  }
  return lines.join('
') + '
';
};
// @openarc:end diamond.makeDiamond

export function makeDiamond(character: string): string {
  const charCode = character.charCodeAt(0);
  const targetCode = character.toUpperCase().charCodeAt(0);

  if (isNaN(charCode) || charCode !== targetCode) {
    throw new Error("Invalid character");
  }

  const startCode = "A".charCodeAt(0);
  const n = targetCode - startCode;

  if (n < 0) {
    throw new Error("Character must be 'A' or greater");
  }

  const lines: string[] = [];

  // Top half including the middle row
  for (let i = 0; i <= n; i++) {
    const currentChar = String.fromCharCode(startCode + i);
    const spaces = " ".repeat(n - i);

    if (i === 0) {
      lines.push(spaces + currentChar + spaces);
    } else {
      const innerSpaces = " ".repeat(2 * i - 1);
      lines.push(spaces + currentChar + innerSpaces + currentChar + spaces);
    }
  }

  // Bottom half (mirror of top half excluding the middle row)
  for (let i = n - 1; i >= 0; i--) {
    lines.push(lines[i]);
  }

  return lines.join("\n") + "\n";
}

