// @openarc:begin transpose.transpose
export const transpose: TransposeFn = (rows) => {
  const maxLen = rows.reduce((max, row) => Math.max(max, row.length), 0);
    const result: string[] = [];
    for (let col = 0; col < maxLen; col++) {
      let newRow = '';
      for (let row = 0; row < rows.length; row++) {
        if (col < rows[row].length) {
          newRow += rows[row][col];
        } else {
          newRow += ' ';
        }
      }
      result.push(newRow);
    }
    return result;
};
// @openarc:end transpose.transpose

export function transpose(rows: string[]): string[] {
  if (rows.length === 0) {
    return [];
  }

  const maxLen = Math.max(...rows.map((row) => row.length));
  const result: string[] = [];

  for (let col = 0; col < maxLen; col++) {
    let newRow = "";
    let hasNonSpace = false;

    for (let rowIdx = 0; rowIdx < rows.length; rowIdx++) {
      const currentRow = rows[rowIdx];
      if (col < currentRow.length) {
        const char = currentRow[col];
        newRow += char;
        if (char !== " ") {
          hasNonSpace = true;
        }
      } else {
        // Pad with space if column index exceeds row length
        newRow += " ";
      }
    }

    // Trim trailing spaces, but only if there is at least one non-space character in the row.
    // If the row is all spaces, we keep it as is (to satisfy the "only spaces" rule).
    if (hasNonSpace) {
      result.push(newRow.replace(/ +$/, ""));
    } else {
      result.push(newRow);
    }
  }

  return result;
}

