// @openarc:begin twelveDays.recite
export const recite: ReciteFn = (startVerse, endVerse) => {
  const gifts = [
    'a Partridge in a Pear Tree',
    'two Turtle Doves',
    'three French Hens',
    'four Calling Birds',
    'five Gold Rings',
    'six Geese-a-Laying',
    'seven Swans-a-Swimming',
    'eight Maids-a-Milking',
    'nine Ladies Dancing',
    'ten Lords-a-Leaping',
    'eleven Pipers Piping',
    'twelve Drummers Drumming'
  ];

  const days = [
    'first', 'second', 'third', 'fourth', 'fifth', 'sixth',
    'seventh', 'eighth', 'ninth', 'tenth', 'eleventh', 'twelfth'
  ];

  function verse(n: number): string {
    let lines = [];
    for (let i = n; i >= 1; i--) {
      if (n > 1 && i === 1) {
        lines.push('and ' + gifts[i - 1]);
      } else {
        lines.push(gifts[i - 1]);
      }
    }
    return 'On the ' + days[n - 1] + ' day of Christmas my true love gave to me: ' + lines.join(', ') + '.\n';
  }

  return gifts.slice(startVerse - 1, endVerse).map((gift, i) => verse(startVerse + i)).join('\n');
};
// @openarc:end twelveDays.recite

export function recite(startVerse: number, endVerse: number): string {
  if (startVerse < 1 || endVerse > 12 || startVerse > endVerse) {
    throw new Error("Invalid verse range");
  }

  const gifts = [
    "a Partridge in a Pear Tree",
    "two Turtle Doves",
    "three French Hens",
    "four Calling Birds",
    "five Gold Rings",
    "six Geese-a-Laying",
    "seven Swans-a-Swimming",
    "eight Maids-a-Milking",
    "nine Ladies Dancing",
    "ten Lords-a-Leaping",
    "eleven Pipers Piping",
    "twelve Drummers Drumming",
  ];

  const days = [
    "first",
    "second",
    "third",
    "fourth",
    "fifth",
    "sixth",
    "seventh",
    "eighth",
    "ninth",
    "tenth",
    "eleventh",
    "twelfth",
  ];

  const verses: string[] = [];

  for (let i = startVerse; i <= endVerse; i++) {
    const currentGifts = gifts.slice(0, i);
    let verseText = `On the ${days[i - 1]} day of Christmas my true love gave to me: `;

    // Build the list of gifts in reverse order
    for (let j = i - 1; j >= 0; j--) {
      if (j === 0 && i > 1) {
        verseText += `and ${currentGifts[j]}`;
      } else {
        verseText += `${currentGifts[j]}`;
      }

      if (j > 0) {
        verseText += ", ";
      }
    }

    verses.push(verseText + ".");
  }

  return verses.join("\n");
}

