// @openarc:begin variableLengthQuantity.decode
export const decode: DecodeFn = (bytes) => {
  const result: number[] = [];
    let accumulator = 0;
    let continuation = true;

    for (let i = 0; i < bytes.length; i++) {
      const byte = bytes[i];
      accumulator = (accumulator << 7) | (byte & 0x7f);
      continuation = (byte & 0x80) !== 0;

      if (!continuation) {
        result.push(accumulator);
        accumulator = 0;
      }
    }

    if (continuation) {
      throw new Error('Incomplete sequence');
    }

    return result;
};
// @openarc:end variableLengthQuantity.decode

export function encode(numbers: number[]): number[] {
  const result: number[] = [];

  for (const num of numbers) {
    if (num < 0 || num > 0xFFFFFFFF) {
      throw new Error("Number out of range for 32-bit unsigned integer");
    }

    if (num === 0) {
      result.push(0);
      continue;
    }

    const bytes: number[] = [];
    let n = num;

    while (n > 0) {
      const byte = n & 0x7F;
      n >>= 7;
      bytes.unshift(byte);
    }

    // Set continuation bit for all bytes except the last one
    for (let i = 0; i < bytes.length - 1; i++) {
      bytes[i] |= 0x80;
    }

    result.push(...bytes);
  }

  return result;
}

export function decode(bytes: number[]): number[] {
  const result: number[] = [];
  let currentNumber = 0;
  let bitsCollected = 0;

  for (const byte of bytes) {
    // Validate byte range
    if (byte < 0 || byte > 255) {
      throw new Error("Invalid byte value");
    }

    if ((byte & 0x80) === 0) {
      // Last byte of the sequence
      if (bitsCollected === 0) {
        // Single byte number (0-127)
        result.push(byte);
      } else {
        // Multi-byte number finished
        // Shift left by 7 for each previous byte and add current byte
        let value = 0;
        for (let i = 0; i < bitsCollected; i++) {
          value = (value << 7) | (currentNumber & 0x7F);
        }
        value = (value << 7) | byte;

        if (value > 0xFFFFFFFF) {
          throw new Error("Decoded number exceeds 32-bit unsigned integer range");
        }
        result.push(value);
      }
      bitsCollected = 0;
      currentNumber = 0;
    } else {
      // Not the last byte
      bitsCollected++;
      currentNumber = byte;
    }
  }

  // If we ended without finishing a number (continuation bit set on last byte)
  if (bitsCollected > 0) {
    throw new Error("Incomplete variable-length quantity");
  }

  return result;
}

export function answer(question: string): number {
  if (!question || typeof question !== "string") {
    throw new Error("Invalid question");
  }

  const trimmed = question.trim();
  if (!trimmed.startsWith("What is ")) {
    throw new Error("Unknown operation");
  }

  // Extract the expression part between "What is " and the final "?"
  const expression = trimmed.slice(8, -1).trim();
  if (!expression) {
    throw new Error("Syntax error");
  }

  // Tokenize the expression
  // We split by spaces, but we need to handle negative numbers correctly.
  // A simple regex split might break on negative numbers if they are at the start or after an operator.
  // Strategy: Match numbers (including negatives) and operators as tokens.

  const tokens: string[] = [];
  let i = 0;
  const len = expression.length;

  while (i < len) {
    const char = expression[i];

    // Check for operators
    if (["+", "-", "*", "/"].includes(char)) {
      tokens.push(char);
      i++;
      continue;
    }

    // Check for numbers (including negative numbers)
    // A number can start with a minus sign if it's the first token or follows an operator
    let numStr = "";
    if (char === "-" && (i === 0 || ["+", "-", "*", "/"].includes(expression[i - 1]))) {
      // Potential negative number
      let j = i + 1;
      while (j < len && (expression[j] >= "0" && expression[j] <= "9")) {
        numStr += expression[j];
        j++;
      }
      if (numStr === "") {
        // It was just a minus sign, which is invalid syntax in this context unless it's part of a number
        // But we handled the case where it starts a number. If no digits follow, it's an error.
        // However, we need to be careful: "5 minus -3" -> tokens: "5", "minus", "-3"
        // Our logic above handles the '-' as an operator if it follows an operator.
        // If it's at the start, it's a negative number.
        // If it follows a number (e.g. "5 -"), that's invalid syntax handled later.
        throw new Error("Syntax error");
      }
      tokens.push("-" + numStr);
      i = j;
      continue;
    }

    // Check for digits
    if (char >= "0" && char <= "9") {
      let j = i;
      while (j < len && expression[j] >= "0" && expression[j] <= "9") {
        numStr += expression[j];
        j++;
      }
      tokens.push(numStr);
      i = j;
      continue;
    }

    // If we encounter anything else, it's invalid
    throw new Error("Syntax error");
  }

  // Validate tokens
  if (tokens.length === 0) {
    throw new Error("Syntax error");
  }

  // Parse numbers and operators
  // We expect: Number, (Operator Number)*
  // Or just: Number

  const numbers: number[] = [];
  const operators: string[] = [];

  let tokenIdx = 0;

  // First token must be a number
  if (!/^-?\d+$/.test(tokens[tokenIdx])) {
    throw new Error("Syntax error");
  }
  numbers.push(parseInt(tokens[tokenIdx], 10));
  tokenIdx++;

  while (tokenIdx < tokens.length) {
    const token = tokens[tokenIdx];

    // Check if operator
    if (["+", "-", "*", "/"].includes(token)) {
      operators.push(token);
      tokenIdx++;

      // Next token must be a number
      if (tokenIdx >= tokens.length || !/^-?\d+$/.test(tokens[tokenIdx])) {
        throw new Error("Syntax error");
      }
      numbers.push(parseInt(tokens[tokenIdx], 10));
      tokenIdx++;
    } else {
      // Unexpected token
      throw new Error("Syntax error");
    }
  }

  // Evaluate left-to-right
  let result = numbers[0];

  for (let i = 0; i < operators.length; i++) {
    const op = operators[i];
    const nextNum = numbers[i + 1];

    switch (op) {
      case "+":
        result += nextNum;
        break;
      case "-":
        result -= nextNum;
        break;
      case "*":
        result *= nextNum;
        break;
      case "/":
        if (nextNum === 0) {
          throw new Error("Division by zero");
        }
        result = Math.trunc(result / nextNum);
        break;
      default:
        throw new Error("Unknown operation");
    }
  }

  return result;
}
